from datetime import datetime, timedelta

urgent_tag = env.ref('cater.tag_urgent', raise_if_not_found=False)
if urgent_tag and record.event_date:
    days_until_event = (record.event_date - datetime.now().date()).days
    if days_until_event <= 7 and days_until_event >= 0:
        if urgent_tag not in record.tag_ids:
            record.tag_ids = [(4, urgent_tag.id)]
            record.message_post(body='Tagged as Urgent - Event is within 7 days.')

from datetime import datetime

urgent_tag = env.ref('cater.tag_urgent', raise_if_not_found=False)
if urgent_tag and record.event_date:
    if record.event_date < datetime.now().date():
        if urgent_tag in record.tag_ids:
            record.tag_ids = [(3, urgent_tag.id)]
            record.message_post(body='Removed Urgent tag - Event date has passed.')
